57. function fromZodResult<ZodInput, ZodOutput extends Val>(
58.   input: SafeParseReturnType<ZodInput, ZodOutput>,
59. ): Result<ZodOutput, ZodError<ZodInput>> {
60.   return input.success ? Result.ok(input.data) : Result.err(input.error);
61. }
