68.   T,
69.   SafeParseReturnType<unknown, T> | Promise<unknown>
70. >;
71. 
72. function fromNullable<
73.   T extends Val,
74.   ErrForNull extends Val,
75.   ErrForUndefined extends Val,
76. >(
77.   input: Nullish<T>,
78.   errForNull: ErrForNull,
79.   errForUndefined: ErrForUndefined,
80. ): Result<T, ErrForNull | ErrForUndefined> {
